From 557244f6284f30613f2d61f14b579303165876c3 Mon Sep 17 00:00:00 2001
From: Christophe JAILLET <christophe.jaillet@wanadoo.fr>
Date: Sun, 31 Jul 2022 11:55:38 +0200
Subject: [PATCH] mfd: lp8788: Fix an error handling path in lp8788_irq_init()
 and lp8788_irq_init()

In lp8788_irq_init(), if an error occurs after a successful
irq_domain_add_linear() call, it must be undone by a corresponding
irq_domain_remove() call.

irq_domain_remove() should also be called in lp8788_irq_exit() for the same
reason.

Fixes: eea6b7cc53aa ("mfd: Add lp8788 mfd driver")
Signed-off-by: Christophe JAILLET <christophe.jaillet@wanadoo.fr>
Signed-off-by: Lee Jones <lee@kernel.org>
Link: https://lore.kernel.org/r/bcd5a72c9c1c383dd6324680116426e32737655a.1659261275.git.christophe.jaillet@wanadoo.fr

diff --git a/drivers/mfd/lp8788-irq.c b/drivers/mfd/lp8788-irq.c
index 348439a3fbbd..39006297f3d2 100644
--- a/drivers/mfd/lp8788-irq.c
+++ b/drivers/mfd/lp8788-irq.c
@@ -175,6 +175,7 @@ int lp8788_irq_init(struct lp8788 *lp, int irq)
 				IRQF_TRIGGER_FALLING | IRQF_ONESHOT,
 				"lp8788-irq", irqd);
 	if (ret) {
+		irq_domain_remove(lp->irqdm);
 		dev_err(lp->dev, "failed to create a thread for IRQ_N\n");
 		return ret;
 	}
@@ -188,4 +189,6 @@ void lp8788_irq_exit(struct lp8788 *lp)
 {
 	if (lp->irq)
 		free_irq(lp->irq, lp->irqdm);
+	if (lp->irqdm)
+		irq_domain_remove(lp->irqdm);
 }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug arises from the lack of proper error handling in the `lp8788_irq_init()` function. Specifically, if an error occurs after successfully adding an IRQ domain with `irq_domain_add_linear()`, the previously allocated IRQ domain is not removed, leading to a resource leak. Additionally, the `lp8788_irq_exit()` function also fails to remove the IRQ domain when exiting, which can further exacerbate resource management issues.

        Commit message:
        mfd: lp8788: Fix an error handling path in lp8788_irq_init()
 and lp8788_irq_init()

In lp8788_irq_init(), if an error occurs after a successful
irq_domain_add_linear() call, it must be undone by a corresponding
irq_domain_remove() call.

irq_domain_remove() should also be called in lp8788_irq_exit() for the same
reason.

Fixes: eea6b7cc53aa ("mfd: Add lp8788 mfd driver")
Signed-off-by: Christophe JAILLET <christophe.jaillet@wanadoo.fr>
Signed-off-by: Lee Jones <lee@kernel.org>
Link: https://lore.kernel.org/r/bcd5a72c9c1c383dd6324680116426e32737655a.1659261275.git.christophe.jaillet@wanadoo.fr  

        Patch:

 int lp8788_irq_init(struct lp8788 *lp, int irq)
 {
 	struct lp8788_irq_data *irqd;
 	int ret;

 	if (irq <= 0) {
 		dev_warn(lp->dev, "invalid irq number: %d\n", irq);
 		return 0;
 	}

 	irqd = devm_kzalloc(lp->dev, sizeof(*irqd), GFP_KERNEL);
 	if (!irqd)
 		return -ENOMEM;

 	irqd->lp = lp;
 	irqd->domain = irq_domain_add_linear(lp->dev->of_node, LP8788_INT_MAX,
 					&lp8788_domain_ops, irqd);
 	if (!irqd->domain) {
 		dev_err(lp->dev, "failed to add irq domain err\n");
 		return -EINVAL;
 	}

 	lp->irqdm = irqd->domain;
 	mutex_init(&irqd->irq_lock);

 	ret = request_threaded_irq(irq, NULL, lp8788_irq_handler,
 				IRQF_TRIGGER_FALLING | IRQF_ONESHOT,
 				"lp8788-irq", irqd);
 	if (ret) {
+		irq_domain_remove(lp->irqdm);
 		dev_err(lp->dev, "failed to create a thread for IRQ_N\n");
 		return ret;
 	}

 	lp->irq = irq;

 	return 0;
 }

 void lp8788_irq_exit(struct lp8788 *lp)
 {
 	if (lp->irq)
 		free_irq(lp->irq, lp->irqdm);
+	if (lp->irqdm)
+		irq_domain_remove(lp->irqdm);
 }
